            ds = dist_cheb(sx, sy, rx, ry)
            do = dist_cheb(ox, oy, rx, ry)
            score = (ds - do, ds)  # lexicographic
            if best is None or score < best_score:
                best = (rx, ry)
                best_score = score
        tx, ty = best
    else:
        tx, ty = w // 2, h // 2

    chosen = (0, 0)
    chosen_val = None
