            # "Edge-ness" boosts resources likely contested by edge patrol.
            edge = min(rx, w - 1 - rx) + min(ry, h - 1 - ry)
            edge_score = (w + h - 2) - edge  # higher near edges
            val = (do, -edge_score, rx, ry)
            if best_block is None or val < best_block[0]:
                best_block = (val, (rx, ry))
        tx, ty = best_block[1]
        # If we are already much closer, switch to our own best pick.
